export const getCreateSpaceUrl = () => {
  return `${process.env.WBD_API_BASE_URL ?? ""}/api/v1/spaces`;
};

/**
 * @summary Create a space
 */
export const createSpace = async (
  createSpaceBody: CreateSpaceBody,
  options?: RequestInit,
): Promise<createSpaceResponse> => {
  const res = await fetch(getCreateSpaceUrl(), {
    ...options,
    method: "POST",
    headers: { "Content-Type": "application/json", ...options?.headers },
    body: JSON.stringify(createSpaceBody),
  });

  const body = [204, 205, 304].includes(res.status) ? null : await res.text();

  const data: createSpaceResponse["data"] = body ? JSON.parse(body) : {};
  return {
    data,
    status: res.status,
    headers: res.headers,
  } as createSpaceResponse;
};

